// WorkspaceServiceHandler is an implementation of the codepuppy.v1.WorkspaceService service.
type WorkspaceServiceHandler interface {
	// Returns the workspaces the service has open.
	ListWorkspaces(context.Context, *connect.Request[v1.ListWorkspacesRequest]) (*connect.Response[v1.ListWorkspacesResponse], error)
	// Closes a workspace: kills its background processes and MCP servers.
	CloseWorkspace(context.Context, *connect.Request[v1.CloseWorkspaceRequest]) (*connect.Response[v1.CloseWorkspaceResponse], error)
	// Describes the sandbox commands run in, one line each.
	GetSandbox(context.Context, *connect.Request[v1.GetSandboxRequest]) (*connect.Response[v1.GetSandboxResponse], error)
	// Returns every agent and which is active.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// Makes an agent the active one.
	SetAgent(context.Context, *connect.Request[v1.SetAgentRequest]) (*connect.Response[v1.SetAgentResponse], error)
	// Returns the model the active agent runs on.
	GetModel(context.Context, *connect.Request[v1.GetModelRequest]) (*connect.Response[v1.GetModelResponse], error)
	// Switches every unpinned agent to a model.
	SetModel(context.Context, *connect.Request[v1.SetModelRequest]) (*connect.Response[v1.SetModelResponse], error)
	// Pins an agent to a model and saves the pin (UNKNOWN_AGENT).
	PinModel(context.Context, *connect.Request[v1.PinModelRequest]) (*connect.Response[v1.PinModelResponse], error)
	// Returns an agent to the configured model, or its own default.
	UnpinModel(context.Context, *connect.Request[v1.UnpinModelRequest]) (*connect.Response[v1.UnpinModelResponse], error)
	// Returns every model's generation settings, or one model's.
	GetModelSettings(context.Context, *connect.Request[v1.GetModelSettingsRequest]) (*connect.Response[v1.GetModelSettingsResponse], error)
	// Changes a model's generation settings and saves them (BAD_MODEL_REF,
	// INVALID_SETTING; nothing changes on error).
	UpdateModelSettings(context.Context, *connect.Request[v1.UpdateModelSettingsRequest]) (*connect.Response[v1.UpdateModelSettingsResponse], error)
	// Returns the settings /set changes, plus model, agent and reply language.
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	// Changes a setting for the workspace (UNKNOWN_SETTING, INVALID_AGENCY).
	SetSetting(context.Context, *connect.Request[v1.SetSettingRequest]) (*connect.Response[v1.SetSettingResponse], error)
	// Returns the skills found, or those matching a query.
	ListSkills(context.Context, *connect.Request[v1.ListSkillsRequest]) (*connect.Response[v1.ListSkillsResponse], error)
	// Returns one skill (SKILL_NOT_FOUND).
	GetSkill(context.Context, *connect.Request[v1.GetSkillRequest]) (*connect.Response[v1.GetSkillResponse], error)
	// Returns skill scripts' environments (SCRIPTS_DISABLED).
	ListEnvs(context.Context, *connect.Request[v1.ListEnvsRequest]) (*connect.Response[v1.ListEnvsResponse], error)
	// Removes one environment.
	RemoveEnv(context.Context, *connect.Request[v1.RemoveEnvRequest]) (*connect.Response[v1.RemoveEnvResponse], error)
	// Removes environments no allowed script needs, and incomplete ones.
	PruneEnvs(context.Context, *connect.Request[v1.PruneEnvsRequest]) (*connect.Response[v1.PruneEnvsResponse], error)
	// Returns the configured MCP servers.
	ListMCPServers(context.Context, *connect.Request[v1.ListMCPServersRequest]) (*connect.Response[v1.ListMCPServersResponse], error)
	// Returns what the active agent can use.
	ListTools(context.Context, *connect.Request[v1.ListToolsRequest]) (*connect.Response[v1.ListToolsResponse], error)
	// Re-reads project instruction files and returns their paths.
	ReloadMemory(context.Context, *connect.Request[v1.ReloadMemoryRequest]) (*connect.Response[v1.ReloadMemoryResponse], error)
	// Appends a note to the project instruction file.
	AddMemory(context.Context, *connect.Request[v1.AddMemoryRequest]) (*connect.Response[v1.AddMemoryResponse], error)
	// Returns the languages with an interface catalog.
	ListLocales(context.Context, *connect.Request[v1.ListLocalesRequest]) (*connect.Response[v1.ListLocalesResponse], error)
	// Sets the language the model replies in and saves it (UNKNOWN_LOCALE).
	// The client switches its own interface language to the returned tag.
	SetLocale(context.Context, *connect.Request[v1.SetLocaleRequest]) (*connect.Response[v1.SetLocaleResponse], error)
	// Returns the turns that changed files, newest first.
	ListCheckpoints(context.Context, *connect.Request[v1.ListCheckpointsRequest]) (*connect.Response[v1.ListCheckpointsResponse], error)
	// Restores the files the latest turn with changes modified
	// (UNDO_CONFLICT unless force).
	Undo(context.Context, *connect.Request[v1.UndoRequest]) (*connect.Response[v1.UndoResponse], error)
	// Returns a diff of the agent's changes this session, or git's.
	GetDiff(context.Context, *connect.Request[v1.GetDiffRequest]) (*connect.Response[v1.GetDiffResponse], error)
	// Returns standing approvals.
	ListApprovals(context.Context, *connect.Request[v1.ListApprovalsRequest]) (*connect.Response[v1.ListApprovalsResponse], error)
	// Revokes approvals by key, or all of them.
	RevokeApprovals(context.Context, *connect.Request[v1.RevokeApprovalsRequest]) (*connect.Response[v1.RevokeApprovalsResponse], error)
	// Reads an image from the workspace for a prompt (IMAGES_DISABLED).
	LoadImage(context.Context, *connect.Request[v1.LoadImageRequest]) (*connect.Response[v1.LoadImageResponse], error)
	// Stores image data (e.g. pasted) for a prompt (IMAGES_DISABLED).
	AddImage(context.Context, *connect.Request[v1.AddImageRequest]) (*connect.Response[v1.AddImageResponse], error)
	// Names the web search provider (NO_FETCH when the agent can't fetch
	// pages, so a search would give it nothing to read).
	GetSearchProvider(context.Context, *connect.Request[v1.GetSearchProviderRequest]) (*connect.Response[v1.GetSearchProviderResponse], error)
	// Searches the web and prepares the prompt that hands the readable results
	// to the agent (NO_FETCH, NO_SEARCH): run it as a turn with fetch_grants
	// set to the links' URLs.
	SearchWeb(context.Context, *connect.Request[v1.SearchWebRequest]) (*connect.Response[v1.SearchWebResponse], error)
}

